import json, re, sys, os
from pathlib import Path

OUT = Path('/Users/kristinarash/DEV/graphify-out')
CHUNKDIR = Path(os.environ['CLAUDE_JOB_DIR']) / 'tmp' / 'chunks'

ID_RE = re.compile(r'^[a-z0-9_]+$')
FILE_TYPES = {'code', 'document', 'paper', 'image', 'rationale', 'concept'}
RELATIONS = {'calls', 'implements', 'references', 'cites', 'conceptually_related_to',
             'shares_data_with', 'semantically_similar_to', 'rationale_for'}
CONF = {'EXTRACTED', 'INFERRED', 'AMBIGUOUS'}
SUFFIX_RE = re.compile(r'_(c|chunk)\d+$')

targets = sorted(OUT.glob('.graphify_chunk_*.json'))
if not targets:
    print('no chunk files found')
    sys.exit(1)

allok = True
for cf in targets:
    n = cf.stem.split('_')[-1]
    problems = []
    try:
        d = json.loads(cf.read_text(encoding='utf-8'))
    except Exception as e:
        print(f'chunk {n}: INVALID JSON - {e}')
        allok = False
        continue

    for k in ('nodes', 'edges', 'hyperedges', 'input_tokens', 'output_tokens'):
        if k not in d:
            problems.append(f'missing top-level key: {k}')

    listed = set()
    cl = CHUNKDIR / f'chunk_{int(n):02d}.txt'
    if cl.exists():
        listed = {l for l in cl.read_text(encoding='utf-8').splitlines() if l}

    ids = set()
    for nd in d.get('nodes', []):
        i = nd.get('id', '')
        ids.add(i)
        if not ID_RE.match(i or ''):
            problems.append(f'bad id charset: {i!r}')
        if SUFFIX_RE.search(i or ''):
            problems.append(f'chunk-suffixed id: {i!r}')
        if nd.get('file_type') not in FILE_TYPES:
            problems.append(f'bad file_type {nd.get("file_type")!r} on {i}')
        sf = nd.get('source_file')
        if listed and sf not in listed:
            problems.append(f'source_file not verbatim from FILE_LIST: {sf}')

    for e in d.get('edges', []):
        if e.get('relation') not in RELATIONS:
            problems.append(f'bad relation {e.get("relation")!r}')
        if e.get('confidence') not in CONF:
            problems.append(f'bad confidence {e.get("confidence")!r}')
        cs = e.get('confidence_score')
        if cs is None:
            problems.append('edge missing confidence_score')
        elif e.get('confidence') == 'EXTRACTED' and cs != 1.0:
            problems.append(f'EXTRACTED edge with score {cs}')
        elif e.get('confidence') == 'INFERRED' and cs == 0.5:
            problems.append('INFERRED edge with banned 0.5')
        for endp in ('source', 'target'):
            if e.get(endp) not in ids:
                problems.append(f'edge {endp} not a node in this chunk: {e.get(endp)}')

    uniq = []
    seen = set()
    for p in problems:
        key = p.split(':')[0]
        if key not in seen or len(uniq) < 8:
            seen.add(key)
            uniq.append(p)

    status = 'OK' if not problems else f'{len(problems)} problems'
    print(f'chunk {n}: {len(d.get("nodes",[]))} nodes, {len(d.get("edges",[]))} edges, '
          f'{len(d.get("hyperedges",[]))} hyperedges -> {status}')
    for p in uniq[:8]:
        print('    -', p)
    if problems:
        allok = False

print('\nRESULT:', 'ALL CHUNKS CONFORM' if allok else 'CONFORMANCE ISSUES FOUND')

